function shuffle(items,rng=Math.random){let a=[...items];for(let i=a.length-1;i>0;i--){let j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function makeBank(level){
 if(level>=4)return ADVANCED[level];
 if(level===1)return FACTS.map(f=>({...f,wrong:f.wrong.slice(0,2)}));
 if(level===2)return FACTS.map(f=>({...f,id:`c-${f.id}`,q:`다음 설명에 알맞은 답을 고르세요.\n“${f.clue}”`}));
 return FACTS.map((f,index)=>{const same=FACTS.filter(v=>v.topic===f.topic&&v.id!==f.id);const others=[same[index%same.length],same[(index+3)%same.length],same[(index+6)%same.length]];const a=`${f.clue} → ${f.a}`;return {...f,id:`m-${f.id}`,q:'설명과 답이 바르게 연결된 것을 고르세요.',a,wrong:others.map(g=>`${g.clue} → ${g.wrong[0]}`),why:`바른 연결: ${f.clue} → ${f.a}\n${f.why}`};});
}
function createExam(level,previous=[],rng=Math.random){if(!Number.isInteger(level)||level<1||level>5)throw Error('난이도는 1~5로 선택해 주세요.');let bank=makeBank(level);let result=[];for(let t=0;t<4;t++){let pool=bank.filter(q=>q.topic===t);let fresh=shuffle(pool.filter(q=>!previous.includes(q.id)),rng);let old=shuffle(pool.filter(q=>previous.includes(q.id)),rng);result.push(...[...fresh,...old].slice(0,5));}return shuffle(result,rng).map(q=>({...q,options:shuffle([q.a,...q.wrong],rng)}));}
