function normalizeAnswer(value){return String(value??'').normalize('NFKC').trim().replace(/(입니다|이에요|예요|이다|이요|요)[.!。]?$/,'').replace(/[\s·ㆍ,，.。!！?？:：\-—–()（）]/g,'').toLowerCase();}
function isAnswered(q,answers){return answers[q.id]!==undefined&&String(answers[q.id]).trim()!=='';}
function isCorrect(q,value){if(value==null)return false;if(q.type!=='short')return value===q.a;const accepted=[q.a,...(q.accepted??[]),...(ALIASES[q.a]??[])];return accepted.some(a=>normalizeAnswer(a)===normalizeAnswer(value));}
